    <div class="container">
        <h1>📝 Minhas Anotações</h1>
        <p class="subtitle">Escreva e salve suas anotações rapidamente</p>

        <input
            type="text"
            class="input-titulo"
            id="titulo"
            placeholder="Título da anotação (opcional)"
            maxlength="60"
        />

        <textarea
            id="anotacao"
            placeholder="Escreva sua anotação aqui..."
            oninput="atualizarContador()"
        ></textarea>

        <div class="contador" id="contador">0 caracteres</div>

        <div class="botoes">
            <button class="btn-salvar" onclick="salvarAnotacao()">💾 Salvar</button>
            <button class="btn-copiar" onclick="copiarTexto()">📋 Copiar</button>
            <button class="btn-limpar" onclick="limparCampos()">🗑️ Limpar</button>
        </div>

        <div class="lista-anotacoes" id="lista-anotacoes">
            <h2>📌 Anotações Salvas</h2>
            <p class="mensagem" id="mensagem-vazia">Nenhuma anotação salva ainda.</p>
        </div>
    </div>

    <div class="toast" id="toast"></div>

    <script>
        let anotacoes = JSON.parse(localStorage.getItem('anotacoes')) || [];

        function atualizarContador() {
            const texto = document.getElementById('anotacao').value;
            document.getElementById('contador').textContent = texto.length + ' caracteres';
        }

        function mostrarToast(msg) {
            const toast = document.getElementById('toast');
            toast.textContent = msg;
            toast.style.display = 'block';
            setTimeout(() => toast.style.display = 'none', 2500);
        }

        function salvarAnotacao() {
            const titulo = document.getElementById('titulo').value.trim();
            const texto = document.getElementById('anotacao').value.trim();

            if (!texto) {
                alert('Escreva algo antes de salvar!');
                return;
            }

            const nova = {
                id: Date.now(),
                titulo: titulo || 'Sem título',
                texto: texto,
                data: new Date().toLocaleString('pt-BR')
            };

            anotacoes.unshift(nova);
            localStorage.setItem('anotacoes', JSON.stringify(anotacoes));
            renderizarAnotacoes();
            limparCampos();
            mostrarToast('✅ Anotação salva!');
        }

        function excluirAnotacao(id) {
            anotacoes = anotacoes.filter(a => a.id !== id);
            localStorage.setItem('anotacoes', JSON.stringify(anotacoes));
            renderizarAnotacoes();
            mostrarToast('🗑️ Anotação excluída!');
        }

        function copiarTexto() {
            const texto = document.getElementById('anotacao').value;
            if (!texto) {
                alert('Nada para copiar!');
                return;
            }
            navigator.clipboard.writeText(texto).then(() => {
                mostrarToast('📋 Texto copiado!');
            });
        }

        function limparCampos() {
            document.getElementById('titulo').value = '';
            document.getElementById('anotacao').value = '';
            document.getElementById('contador').textContent = '0 caracteres';
        }

        function renderizarAnotacoes() {
            const lista = document.getElementById('lista-anotacoes');
            const vazia = document.getElementById('mensagem-vazia');

            // Remove cards antigos
            const cards = lista.querySelectorAll('.anotacao-card');
            cards.forEach(c => c.remove());

            if (anotacoes.length === 0) {
                vazia.style.display = 'block';
            } else {
                vazia.style.display = 'none';
                anotacoes.forEach(a => {
                    const card = document.createElement('div');
                    card.className = 'anotacao-card';
                    card.innerHTML = `
                        <div class="card-titulo">${a.titulo}</div>
                        <div class="card-texto">${a.texto}</div>
                        <div class="card-data">🕒 ${a.data}</div>
                        <button class="btn-excluir" onclick="excluirAnotacao(${a.id})">✕ Excluir</button>
                    `;
                    lista.appendChild(card);
                });
            }
        }

        // Carrega ao iniciar
        renderizarAnotacoes();
    </script>

</body>
