## content.js

```javascript
(() => {
  // ─── Config ───────────────────────────────────────────────────────────────
  const TARGET_CLASSES = [
    "v-card__text",
    "headline",
    "text-center",
    "px-0"
  ];

  const HIGHLIGHT_STYLES = {
    outline:          "3px solid red",
    outlineOffset:    "2px",
    backgroundColor:  "rgba(255, 0, 0, 0.12)",
    color:            "red",
    transition:       "all 0.3s ease",
    position:         "relative",
    zIndex:           "9999"
  };

  const BADGE_STYLES = {
    position:         "absolute",
    top:              "0",
    right:            "0",
    backgroundColor:  "red",
    color:            "white",
    fontSize:         "10px",
    fontWeight:       "bold",
    padding:          "2px 5px",
    borderRadius:     "0 0 0 4px",
    zIndex:           "10000",
    pointerEvents:    "none",
    fontFamily:       "monospace",
    lineHeight:       "1.4"
  };

  let highlightEnabled  = true;
  let observerActive    = false;
  let foundCount        = 0;

  // ─── Helpers ──────────────────────────────────────────────────────────────

  /**
   * Check whether an element has ALL the required classes.
   */
  function matchesTargetClass(element) {
    return TARGET_CLASSES.every(cls => element.classList.contains(cls));
  }

  /**
   * Apply red-highlight styles + an info badge to a single element.
   */
  function applyHighlight(element) {
    if (element.dataset.highlighted === "true") return; // already done

    // Store original styles for potential rollback
    element.dataset.originalOutline         = element.style.outline          || "";
    element.dataset.originalBg              = element.style.backgroundColor  || "";
    element.dataset.originalColor           = element.style.color            || "";
    element.dataset.originalOutlineOffset   = element.style.outlineOffset    || "";
    element.dataset.originalPosition        = element.style.position         || "";
    element.dataset.originalZIndex          = element.style.zIndex           || "";
    element.dataset.originalTransition      = element.style.transition       || "";

    // Apply highlight styles
    Object.assign(element.style, HIGHLIGHT_STYLES);

    // Force visible position context for the badge
    const computedPos = window.getComputedStyle(element).position;
    if (computedPos === "static") {
      element.style.position = "relative";
    }

    // Create badge
    const badge       = document.createElement("span");
    badge.className   = "__ext-highlight-badge__";
    badge.textContent = "⚑ highlighted";
    Object.assign(badge.style, BADGE_STYLES);
    element.appendChild(badge);

    element.dataset.highlighted = "true";
    foundCount++;

    console.info(
      `%c[Element Highlighter]%c Found & highlighted element #${foundCount}`,
      "color: red; font-weight: bold;",
      "color: inherit;",
      element
    );
  }

  /**
   * Remove highlight from a single element.
   */
  function removeHighlight(element) {
    if (element.dataset.highlighted !== "true") return;

    element.style.outline         = element.dataset.originalOutline        || "";
    element.style.backgroundColor = element.dataset.originalBg             || "";
    element.style.color           = element.dataset.originalColor          || "";
    element.style.outlineOffset   = element.dataset.originalOutlineOffset  || "";
    element.style.position        = element.dataset.originalPosition       || "";
    element.style.zIndex          = element.dataset.originalZIndex         || "";
    element.style.transition      = element.dataset.originalTransition     || "";

    // Remove badge
    const badge = element.querySelector(".__ext-highlight-badge__");
    if (badge) badge.remove();

    delete element.dataset.highlighted;
    foundCount = Math.max(0, foundCount - 1);
  }

  /**
   * Scan the entire document and highlight all matching elements.
   */
  function scanAndHighlight() {
    if (!highlightEnabled) return;

    const allElements = document.querySelectorAll(
      "." + TARGET_CLASSES.join(".")
    );

    if (allElements.length === 0) {
      // Fallback: broader query then filter manually
      const broader = document.querySelectorAll(".v-card__text");
      broader.forEach(el => {
        if (matchesTargetClass(el)) applyHighlight(el);
      });
    } else {
      allElements.forEach(el => applyHighlight(el));
    }

    // Update popup badge via storage
    chrome.storage.local.set({ highlightCount: foundCount });
  }

  /**
   * Remove all highlights from the page.
   */
  function clearAllHighlights() {
    document.querySelectorAll("[data-highlighted='true']")
      .forEach(el => removeHighlight(el));
    foundCount = 0;
    chrome.storage.local.set({ highlightCount: 0 });
  }

  // ─── MutationObserver (handles dynamic / Vue-rendered content) ────────────

  function startObserver() {
    if (observerActive) return;

    const observer = new MutationObserver(mutations => {
      if (!highlightEnabled) return;

      mutations.forEach(mutation => {
        mutation.addedNodes.forEach(node => {
          if (node.nodeType !== Node.ELEMENT_NODE) return;

          // Check the node itself
          if (matchesTargetClass(node)) applyHighlight(node);

          // Check descendants
          node.querySelectorAll("." + TARGET_CLASSES.join("."))
            .forEach(el => applyHighlight(el));
        });
      });
    });

    observer.observe(document.body, {
      childList:  true,
      subtree:    true,
      attributes: false
    });

    observerActive = true;
    console.info(
      "%c[Element Highlighter]%c MutationObserver active.",
      "color: red; font-weight: bold;",
      "color: inherit;"
    );
  }

  // ─── Message listener (from popup) ────────────────────────────────────────

  chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
    switch (message.action) {

      case "toggle":
        highlightEnabled = message.enabled;
        if (highlightEnabled) {
          scanAndHighlight();
        } else {
          clearAllHighlights();
        }
        sendResponse({ success: true, count: foundCount });
        break;

      case "rescan":
        clearAllHighlights();
        foundCount = 0;
        scanAndHighlight();
        sendResponse({ success: true, count: foundCount });
        break;

      case "getStatus":
        sendResponse({ enabled: highlightEnabled, count: foundCount });
        break;
    }

    return true; // keep channel open for async responses
  });

  // ─── Init ─────────────────────────────────────────────────────────────────

  function init() {
    console.info(
      "%c[Element Highlighter] Extension loaded.",
      "color: red; font-weight: bold;"
    );

    // Read saved toggle state
    chrome.storage.local.get(["highlightEnabled"], result => {
      highlightEnabled = result.highlightEnabled !== false; // default: true
      if (highlightEnabled) {
        scanAndHighlight();
        startObserver();
      }
    });
  }

  // Run after DOM is ready
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  // Also rescan when everything (images, scripts) is fully loaded
  window.addEventListener("load", () => {
    if (highlightEnabled) scanAndHighlight();
  });

})();
```

