            transition: box-shadow 0.1s ease;
        }

        #hint {
            color: rgba(255,255,255,0.35);
            font-size: 0.8rem;
            margin-top: 16px;
            letter-spacing: 1px;
        }
    </style>
</head>
<body>
    <h1>Drag & Swap</h1>
    <div id="grid-container"></div>
    <p id="hint">Click and drag a box to swap it with another</p>

    <script>
        const COLS = 7;
        const ROWS = 6;

        const colors = [
            '#e74c3c', '#e67e22', '#f1c40f', '#2ecc71',
            '#1abc9c', '#3498db', '#9b59b6', '#e91e63',
            '#ff5722', '#00bcd4', '#8bc34a', '#ff9800',
            '#673ab7', '#03a9f4', '#4caf50', '#ffeb3b',
            '#f44336', '#9c27b0', '#2196f3', '#ff4081',
            '#00e676', '#ff6d00', '#d500f9', '#00b0ff',
        ];

        function randomColor() {
            return colors[Math.floor(Math.random() * colors.length)];
        }

        function lightenColor(hex, amount = 40) {
            let r = parseInt(hex.slice(1, 3), 16);
            let g = parseInt(hex.slice(3, 5), 16);
            let b = parseInt(hex.slice(5, 7), 16);
            r = Math.min(255, r + amount);
            g = Math.min(255, g + amount);
            b = Math.min(255, b + amount);
            return `rgb(${r},${g},${b})`;
        }

        const container = document.getElementById('grid-container');
        container.style.gridTemplateColumns = `repeat(${COLS}, 80px)`;

        const total = COLS * ROWS;
        const boxData = [];

        for (let i = 0; i < total; i++) {
            const color = randomColor();
            boxData.push(color);
        }

        function renderGrid() {
            container.innerHTML = '';
            boxData.forEach((color, index) => {
                const box = document.createElement('div');
                box.className = 'box';
                box.dataset.index = index;
                box.style.backgroundColor = color;
                box.style.background = `linear-gradient(135deg, ${color}, ${lightenColor(color, 30)})`;
                container.appendChild(box);
            });
            attachEvents();
        }

        let dragSourceIndex = null;
        let dragClone = null;
        let currentOverIndex = null;

        function attachEvents() {
            const boxes = document.querySelectorAll('.box');

            boxes.forEach(box => {
                box.addEventListener('mousedown', onMouseDown);
            });
        }

        function onMouseDown(e) {
            e.preventDefault();
            const box = e.currentTarget;
            dragSourceIndex = parseInt(box.dataset.index);

            const rect = box.getBoundingClientRect();

            dragClone = document.createElement('div');
            dragClone.id = 'drag-clone';
            dragClone.style.background = box.style.background;
            dragClone.style.backgroundColor = box.style.backgroundColor;
            dragClone.style.left = `${e.clientX}px`;
            dragClone.style.top = `${e.clientY}px`;
            document.body.appendChild(dragClone);

            box.classList.add('dragging');

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        }

        function onMouseMove(e) {
            if (!dragClone) return;

            dragClone.style.left = `${e.clientX}px`;
            dragClone.style.top = `${e.clientY}px`;

            const boxes = document.querySelectorAll('.box');
            let foundOver = null;

            boxes.forEach(box => {
                const idx = parseInt(box.dataset.index);
                box.classList.remove('drag-over');

                if (idx === dragSourceIndex) return;

                const rect = box.getBoundingClientRect();
                if (
                    e.clientX >= rect.left &&
                    e.clientX <= rect.right &&
                    e.clientY >= rect.top &&
                    e.clientY <= rect.bottom
                ) {
                    foundOver = idx;
                    box.classList.add('drag-over');
                }
            });

            currentOverIndex = foundOver;
        }

        function onMouseUp(e) {
            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);

            if (dragClone) {
                dragClone.remove();
                dragClone = null;
            }

            const boxes = document.querySelectorAll('.box');
            boxes.forEach(box => box.classList.remove('drag-over', 'dragging'));

            if (currentOverIndex !== null && currentOverIndex !== dragSourceIndex) {
                const temp = boxData[dragSourceIndex];
                boxData[dragSourceIndex] = boxData[currentOverIndex];
                boxData[currentOverIndex] = temp;
                renderGrid();
                animateSwap(dragSourceIndex, currentOverIndex);
            }

            dragSourceIndex = null;
            currentOverIndex = null;
        }

        function animateSwap(a, b) {
            const boxes = document.querySelectorAll('.box');
            [a, b].forEach(idx => {
                const box = boxes[idx];
                if (box) {
                    box.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s ease';
                    box.style.transform = 'scale(1.18)';
                    box.style.boxShadow = '0 12px 35px rgba(0,0,0,0.5)';
                    setTimeout(() => {
                        box.style.transform = '';
                        box.style.boxShadow = '';
                        setTimeout(() => {
                            box.style.transition = '';
                        }, 300);
                    }, 200);
                }
            });
        }

        renderGrid();
    </script>
</body>
</html>
```

# Razor AJAX Without jQuery

Here are several ways to make AJAX calls in Razor pages/MVC without jQuery:

---

## 1. Using `fetch` API (Modern Approach)

### Basic GET Request
```html
<button onclick="loadData()">Load Data</button>
<div id="result"></div>

<script>
    async function loadData() {
        const response = await fetch('/Home/GetData');
        const data = await response.json();
        document.getElementById('result').innerHTML = data.message;
    }
</script>
```

### POST Request with Anti-Forgery Token
```html
@inject Microsoft.AspNetCore.Antiforgery.IAntiforgery Antiforgery

<form id="myForm">
    @Html.AntiForgeryToken()
    <input type="text" id="name" name="name" />
    <button type="button" onclick="submitForm()">Submit</button>
</form>
<div id="result"></div>

<script>
    async function submitForm() {
        const token = document.querySelector('input[name="__RequestVerificationToken"]').value;

        const formData = new FormData();
        formData.append('name', document.getElementById('name').value);

        const response = await fetch('/Home/SaveData', {
            method: 'POST',
            headers: {
                'RequestVerificationToken': token
            },
            body: formData
        });

        const result = await response.json();
        document.getElementById('result').textContent = result.message;
    }
</script>
```

### POST with JSON Body
```javascript
async function postJson() {
    const token = document.querySelector('input[name="__RequestVerificationToken"]').value;

    const response = await fetch('/Home/SaveData', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'RequestVerificationToken': token
        },
        body: JSON.stringify({ 
            name: 'John', 
            age: 30 
        })
    });

    if (!response.ok) {
        console.error('Error:', response.statusText);
        return;
    }

    const data = await response.json();
    console.log(data);
}
