## 6. Reusable AJAX Helper

```javascript
// wwwroot/js/ajaxHelper.js
const Ajax = {
    getToken() {
        return document.querySelector('input[name="__RequestVerificationToken"]')?.value;
    },

    async get(url) {
        const response = await fetch(url);
        if (!response.ok) throw new Error(response.statusText);
        return response.json();
    },

    async post(url, data) {
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'RequestVerificationToken': this.getToken()
            },
            body: JSON.stringify(data)
        });
        if (!response.ok) throw new Error(response.statusText);
        return response.json();
    },

    async postForm(url, formElement) {
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'RequestVerificationToken': this.getToken()
            },
            body: new FormData(formElement)
        });
        if (!response.ok) throw new Error(response.statusText);
        return response.json();
    }
};

// Usage
Ajax.get('/api/items').then(data => console.log(data));
Ajax.post('/api/save', { name: 'John' }).then(data => console.log(data));
```

