                <div class="topic-color-dot" style="background:${topic.color}"></div>
                <input class="topic-emoji-input" type="text" maxlength="2"
                    value="${topic.emoji}"
                    onchange="updateTopicField(${topic.id}, 'emoji', this.value)"
                    title="Эмодзи темы">
                <input class="topic-name-input" type="text"
                    value="${topic.name}"
                    onchange="updateTopicField(${topic.id}, 'name', this.value)"
                    placeholder="Название темы">
                <button class="btn-del-topic" onclick="deleteTopic(${topic.id})" title="Удалить тему">✕</button>
            </div>
            <textarea class="keywords-input"
                placeholder="ключевое, слово, через, запятую"
                onchange="updateKeywords(${topic.id}, this.value)"
            >${topic.keywords.join(', ')}</textarea>
            <div class="keywords-hint">🔑 Слов: ${topic.keywords.length} — разделяйте запятой</div>
        `;
        list.appendChild(div);
    });

    renderStats();
}

function renderStats() {
    const row = document.getElementById('statsRow');
    const totalKw = topics.reduce((s, t) => s + t.keywords.length, 0);
    row.innerHTML = `
        <div class="stat-chip">Тем: <span>${topics.length}</span></div>
        <div class="stat-chip">Ключевых слов: <span>${totalKw}</span></div>
    `;
}

function updateTopicField(id, field, value) {
    const t = topics.find(t => t.id === id);
    if (t) t[field] = value.trim();
    renderStats();
}

function updateKeywords(id, value) {
    const t = topics.find(t => t.id === id);
    if (t) {
        t.keywords = value.split(',')
            .map(k => k.trim().toLowerCase())
            .filter(k => k.length > 0);
    }
    renderStats();
    // Перерендер подсказки
    renderTopics();
}

