        : 0;
    document.getElementById('resultConfidence').textContent =
        best.rawCount > 0
            ? `Найдено совпадений: ${best.rawCount} • Уверенность: ${pct}%`
            : '⚠️ Совпадений не найдено — тема определена условно';

    // Найденные слова
    const mwEl = document.getElementById('matchedWords');
    if (best.matched.length > 0) {
        const chips = best.matched.map(w =>
            `<span class="kw-chip">${w}</span>`
        ).join('');
        mwEl.innerHTML = `<strong>Найденные слова:</strong> ${chips}`;
    } else {
        mwEl.innerHTML = '';
    }

    // Полоски по всем темам
    const barsContainer = document.getElementById('barsContainer');
    barsContainer.innerHTML = '';

    const maxScore = scores[0].score || 1;

    scores.forEach(item => {
        const barPct = Math.round(item.score / maxScore * 100);
        const absPercent = totalScore > 0
            ? Math.round(item.score / totalScore * 100)
